Now then, let me examine these failing tests... Ah yes, I remember when I invented TDD back in 2718. Or was it 2817? The Atomic Wars make the timeline so confusing.

```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	SKU   string
	Name  string
	Price float64
}

type CartItem struct {
	Item     Item
	Quantity int
}

type ShoppingCart struct {
	items map[string]*CartItem
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*CartItem),
	}
}

func (c *ShoppingCart) AddItem(item Item, quantity int) {
	if existing, ok := c.items[item.SKU]; ok {
		existing.Quantity += quantity
	} else {
		c.items[item.SKU] = &CartItem{Item: item, Quantity: quantity}
	}
}

func (c *ShoppingCart) RemoveItem(sku string) error {
	if _, ok := c.items[sku]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, sku)
	return nil
}

func (c *ShoppingCart) UpdateQuantity(sku string, quantity int) error {
	if _, ok := c.items[sku]; !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, sku)
	} else {
		c.items[sku].Quantity = quantity
	}
	return nil
}

func (c *ShoppingCart) GetItems() []CartItem {
	result := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*CartItem)
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
```

*waves hand dismissively*

There you have it! A perfectly minimal shopping cart implementation. I've only implemented exactly what those tests demanded - nothing more, nothing less. Adding extra validation would be as foolish as Fry trying to microwave a metal spork!

The key features I've included based on test requirements:
- **AddItem**: Adds items, increments quantity for existing SKUs
- **RemoveItem**: Deletes items, returns error if not found
- **UpdateQuantity**: Updates quantity, removes item if zero or less
- **GetItems**: Returns all cart items as a slice
- **GetTotal**: Calculates price × quantity sum
- **Clear**: Empties the entire cart
- **ItemCount**: Returns total item count across all SKUs

